1	import { getCurrentUser } from "@/lib/auth";
2	import { db } from "@/lib/db";
3	import { track, EVENTS } from "@/lib/events";
4	
5	export const dynamic = "force-dynamic";
6	
7	// Thumbs up/down on a finished build. Feeds the learning loop — see
8	// buildRatings() in lib/events.ts.
9	//
10	// Costs no credits and creates no build row: asking someone what they think of
11	// what they already paid for must never itself cost them anything.
12	
13	const RATINGS = new Set(["up", "down"]);
14	
15	/** Optional structured "what was wrong" — kept closed so it stays aggregatable. */
16	const REASONS = new Set([
17	  "looks-generic",
18	  "wrong-content",
19	  "layout-off",
20	  "missing-something",
21	  "broken",
22	  "other",
23	]);
24	
25	export async function POST(req: Request) {
26	  const user = await getCurrentUser();
27	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
28	
29	  const body = (await req.json().catch(() => null)) as {
30	    buildId?: string;
31	    rating?: string;
32	    reason?: string;
33	  } | null;
34	
35	  const { buildId, rating, reason } = body ?? {};
36	  if (!buildId || typeof buildId !== "string" || !rating || !RATINGS.has(rating)) {
37	    return Response.json({ error: "Missing or invalid rating." }, { status: 400 });
38	  }
39	
40	  // Ownership in the same query as the id, so someone else's build id is
41	  // indistinguishable from a nonexistent one — and nobody can seed ratings
42	  // onto builds that aren't theirs.
43	  const build = await db.build.findFirst({
44	    where: { id: buildId, project: { userId: user.id } },
45	    select: { id: true, projectId: true, status: true, repairAttempts: true, model: true },
46	  });
47	  if (!build) return Response.json({ error: "Build not found." }, { status: 404 });
48	
49	  track(EVENTS.buildRated, {
50	    userId: user.id,
51	    props: {
52	      buildId: build.id,
53	      projectId: build.projectId,
54	      rating,
55	      // Recorded alongside the rating so the dashboard can ask the question
56	      // that matters: are the thumbs-down builds the ones that needed repair?
57	      repairAttempts: build.repairAttempts,
58	      model: build.model,
59	      ...(reason && REASONS.has(reason) ? { reason } : {}),
60	    },
61	  });
62	
63	  return Response.json({ ok: true });
64	}
