"use server";

import { refresh } from "next/cache";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { NOTE_MAX, type NoteFormState } from "./ui";

// Writing a support note is the only mutation this inbox performs. Everything
// else on these pages reads.
//
// A "use server" file may only export async functions, so NOTE_MAX and the
// form-state type live in ./ui.tsx and are imported (the type as a type-only
// import, so nothing React-shaped is dragged into the action bundle).

export async function addSupportNote(
  _prev: NoteFormState,
  formData: FormData,
): Promise<NoteFormState> {
  // Server Functions are reachable by direct POST, not only through this UI —
  // so the admin check happens HERE, not merely on the page that renders the
  // form. Same reason getAdminUser() is called on every admin page: a layout
  // is not an authorization boundary.
  const admin = await getAdminUser();
  if (!admin) return { error: "You are not signed in as an admin.", ok: false };

  const rawUserId = formData.get("userId");
  const rawBody = formData.get("body");
  const userId = typeof rawUserId === "string" ? rawUserId : "";
  const body = typeof rawBody === "string" ? rawBody.trim() : "";

  if (!userId) return { error: "Missing the customer this note is about.", ok: false };
  if (!body) return { error: "A note needs something in it.", ok: false };
  if (body.length > NOTE_MAX) {
    return {
      error: `That is ${body.length} characters — keep a note under ${NOTE_MAX}. Summarise rather than paste.`,
      ok: false,
    };
  }

  // Verify the target exists rather than letting the foreign key throw: a 500
  // on a stale tab is a worse answer than a sentence.
  const user = await db.user.findUnique({ where: { id: userId }, select: { id: true } });
  if (!user) return { error: "That customer no longer exists.", ok: false };

  await db.supportNote.create({
    // authorEmail comes from the session, never from the form. Attribution
    // nobody can spoof is the whole point of recording it.
    data: { userId: user.id, authorEmail: admin.email, body },
  });

  // Re-render the current route so the new note appears above the form without
  // a manual reload.
  refresh();

  return { error: null, ok: true };
}

"use client";

import { useActionState } from "react";
import { addSupportNote } from "../../actions";
import { NOTE_FORM_INITIAL, NOTE_MAX, buttonClass } from "../../ui";

// The one write surface in the support inbox.
//
// A client component only so the operator gets a pending state and an inline
// error instead of a full page reload with the note lost. The <form action>
// still posts without JavaScript — React only takes over once hydrated — and
// React clears the textarea itself when the action resolves successfully.

export default function NoteForm({ userId, email }: { userId: string; email: string }) {
  const [state, formAction, pending] = useActionState(addSupportNote, NOTE_FORM_INITIAL);

  return (
    <form action={formAction}>
      <input type="hidden" name="userId" value={userId} />

      <label htmlFor="note-body" className="block text-sm font-medium">
        New note about {email}
      </label>

      {/* Not a placeholder and not a tooltip: this has to be readable while
          the operator is typing, which is the moment it matters. */}
      <p id="note-guidance" className="mt-1 text-xs text-black/60 dark:text-white/60">
        Operator-only — this is never shown to the customer. It is still{" "}
        <strong>disclosable in a data-subject access request</strong>, so write only what you would
        stand behind if this customer read it back to you. Facts and next steps, not opinions about
        the person.
      </p>

      <textarea
        id="note-body"
        name="body"
        rows={4}
        required
        maxLength={NOTE_MAX}
        aria-describedby="note-guidance note-status"
        placeholder="Emailed about the hero section rebuilding on every edit. Reproduced on their project; pointed at the repair loop."
        className="mt-2 w-full resize-y rounded-xl border border-black/10 bg-transparent px-3 py-2 text-sm outline-none placeholder:text-black/40 focus-visible:ring-2 focus-visible:ring-black/40 dark:border-white/10 dark:placeholder:text-white/40 dark:focus-visible:ring-white/40"
      />

      <div className="mt-2 flex flex-wrap items-center gap-3">
        <button type="submit" className={buttonClass} disabled={pending}>
          {pending ? "Saving…" : "Add note"}
        </button>
        <span className="text-xs text-black/50 dark:text-white/50">
          Up to {NOTE_MAX} characters. Notes cannot be edited or deleted from here.
        </span>
      </div>

      {/* One live region for both outcomes, so a screen reader hears the result
          of the submit it just made without the focus moving anywhere. */}
      <p
        id="note-status"
        role="status"
        aria-live="polite"
        className={`mt-2 text-sm ${
          state.error
            ? "text-red-600 dark:text-red-400"
            : "text-emerald-600 dark:text-emerald-400"
        }`}
      >
        {state.error ? state.error : state.ok ? "Note saved." : ""}
      </p>
    </form>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { EVENTS } from "@/lib/events";
import { Empty, Panel, StatTile, formatDateTime } from "../../../users/ui";
import { RatingPill, reasonLabel } from "../../ui";
import NoteForm from "./NoteForm";

export const dynamic = "force-dynamic";

// One customer's support thread: what operators have written down about them,
// and the ratings they left. The two belong on the same page — "this customer
// emailed about X" is only useful next to the evidence of what X was.

const NOTE_LIMIT = 200;
const RATING_LIMIT = 20;

export default async function AdminUserNotesPage({
  params,
}: {
  params: Promise<{ userId: string }>;
}) {
  // Defense in depth — see app/admin/page.tsx. The layout gate is the primary
  // one, but a layout must not be the sole authorization boundary.
  if (!(await getAdminUser())) notFound();

  const { userId } = await params;

  const user = await db.user.findUnique({
    where: { id: userId },
    select: { id: true, email: true, name: true, role: true, createdAt: true },
  });
  if (!user) notFound();

  const [notes, noteTotal, ratingRows] = await Promise.all([
    db.supportNote.findMany({
      where: { userId: user.id },
      // Served straight off the @@index([userId, createdAt]) on SupportNote.
      orderBy: { createdAt: "desc" },
      take: NOTE_LIMIT,
      select: { id: true, createdAt: true, authorEmail: true, body: true },
    }),
    db.supportNote.count({ where: { userId: user.id } }),
    db.event.findMany({
      where: { userId: user.id, name: EVENTS.buildRated },
      orderBy: { createdAt: "desc" },
      take: RATING_LIMIT,
      select: { id: true, createdAt: true, props: true },
    }),
  ]);

  const ratings = ratingRows.map((row) => {
    const p =
      row.props !== null && typeof row.props === "object" && !Array.isArray(row.props)
        ? (row.props as Record<string, unknown>)
        : {};
    const rating = typeof p.rating === "string" ? p.rating : null;
    return {
      id: row.id,
      createdAt: row.createdAt,
      rating: rating === "up" || rating === "down" ? rating : null,
      reason: typeof p.reason === "string" ? p.reason : null,
      repairAttempts: typeof p.repairAttempts === "number" ? p.repairAttempts : null,
    };
  });

  const up = ratings.filter((r) => r.rating === "up").length;
  const down = ratings.filter((r) => r.rating === "down").length;

  return (
    <div className="mx-auto max-w-4xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin/feedback/notes"
          className="rounded text-xs text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
        >
          ← Operator notes
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">{user.email}</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          {user.name ? `${user.name} · ` : ""}
          {user.role} · signed up {formatDateTime(user.createdAt)} ·{" "}
          <Link
            href={`/admin/users/${user.id}`}
            className="rounded underline underline-offset-4 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
          >
            billing &amp; builds →
          </Link>
        </p>
        <p className="mt-1 font-mono text-xs text-black/40 dark:text-white/40">{user.id}</p>
      </div>

      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-3">
        <StatTile label="Notes" value={noteTotal} hint="operator-written, never customer-facing" />
        <StatTile
          label="Ratings"
          value={
            <>
              <span className="text-emerald-600 dark:text-emerald-400">{up}</span>
              <span className="text-black/30 dark:text-white/30"> / </span>
              <span className="text-red-600 dark:text-red-400">{down}</span>
            </>
          }
          hint={`up / down, last ${RATING_LIMIT}`}
        />
        <StatTile
          label="Last note"
          value={
            notes.length === 0 ? (
              <span className="text-black/30 dark:text-white/30">—</span>
            ) : (
              <span className="text-base">{formatDateTime(notes[0].createdAt).slice(0, 10)}</span>
            )
          }
          hint={notes.length === 0 ? "nobody has written one" : `by ${notes[0].authorEmail}`}
        />
      </div>

      <div className="mb-8">
        <Panel
          title="Add a note"
          subtitle="For the next person who picks up this thread — what the customer said, what was checked, what happens next."
        >
          <NoteForm userId={user.id} email={user.email} />
        </Panel>
      </div>

      <div className="mb-8">
        <Panel
          title="Notes"
          subtitle={
            noteTotal > notes.length
              ? `Newest first. Showing the most recent ${notes.length} of ${noteTotal}.`
              : "Newest first. Append-only — nothing in the app edits or deletes a note."
          }
        >
          {notes.length === 0 ? (
            <Empty>
              No notes on this customer yet. The first one is worth writing even if it only says
              what they asked about.
            </Empty>
          ) : (
            <ol className="space-y-3">
              {notes.map((n) => (
                <li
                  key={n.id}
                  className="rounded-xl border border-black/10 p-4 dark:border-white/10"
                >
                  <div className="flex flex-wrap items-baseline justify-between gap-x-3 text-xs text-black/50 dark:text-white/50">
                    <span className="font-medium text-black/70 dark:text-white/70">
                      {n.authorEmail}
                    </span>
                    <span className="tabular-nums">{formatDateTime(n.createdAt)}</span>
                  </div>
                  {/* Operator-written and length-capped at the form, so it is
                      shown in full — truncating the one thing a human wrote on
                      purpose would defeat the point of the page. */}
                  <p className="mt-2 text-sm whitespace-pre-wrap break-words">{n.body}</p>
                </li>
              ))}
            </ol>
          )}
        </Panel>
      </div>

      <Panel
        title="What they rated"
        subtitle={`Their own thumbs up/down, newest first, most recent ${RATING_LIMIT}. Context for the notes above — the full inbox is on /admin/feedback.`}
      >
        {ratings.length === 0 ? (
          <Empty>
            This customer has not rated a build. Note that almost nobody has yet — rating collection
            started very recently, so this is silence rather than indifference.
          </Empty>
        ) : (
          <ol className="space-y-1.5">
            {ratings.map((r) => (
              <li key={r.id} className="flex flex-wrap items-baseline gap-x-3 text-sm">
                <span className="w-40 shrink-0 tabular-nums text-xs text-black/50 dark:text-white/50">
                  {formatDateTime(r.createdAt)}
                </span>
                <RatingPill rating={r.rating} />
                <span className="text-black/70 dark:text-white/70">
                  {r.reason ? reasonLabel(r.reason) : "no reason given"}
                </span>
                <span className="text-xs text-black/50 dark:text-white/50">
                  {r.repairAttempts === null
                    ? "repairs not recorded"
                    : r.repairAttempts === 0
                      ? "compiled first try"
                      : `${r.repairAttempts} repair pass(es)`}
                </span>
              </li>
            ))}
          </ol>
        )}
      </Panel>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { Prisma } from "@prisma/client";
import { db } from "@/lib/db";
import { getAdminUser } from "@/lib/auth";
import { Empty, Panel, StatTile, TableFrame, Th, formatDateTime, truncate } from "../../users/ui";
import { buttonClass, controlClass } from "../ui";

export const dynamic = "force-dynamic";

// The way in to per-customer notes: what has been written lately, and a search
// to reach a customer who has no notes yet. Without the search there is no
// route to a customer who never rated a build — which is most of them, and
// exactly the person a support email arrives about.

const RECENT_LIMIT = 50;
const SEARCH_LIMIT = 25;

function first(v: string | string[] | undefined): string {
  if (Array.isArray(v)) return v[0] ?? "";
  return v ?? "";
}

export default async function AdminSupportNotesPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  // Defense in depth — see app/admin/page.tsx.
  if (!(await getAdminUser())) notFound();

  const q = first((await searchParams).q).trim();

  // Same search shape as /admin/users: email, display name, or a raw id pasted
  // out of a log line or a support ticket.
  const where: Prisma.UserWhereInput = q
    ? {
        OR: [
          { email: { contains: q, mode: "insensitive" } },
          { name: { contains: q, mode: "insensitive" } },
          { id: q },
        ],
      }
    : {};

  const [noteTotal, customersWithNotes, recent, matches] = await Promise.all([
    db.supportNote.count(),
    db.user.count({ where: { supportNotes: { some: {} } } }),
    db.supportNote.findMany({
      orderBy: { createdAt: "desc" },
      take: RECENT_LIMIT,
      select: {
        id: true,
        createdAt: true,
        authorEmail: true,
        body: true,
        userId: true,
        user: { select: { email: true } },
      },
    }),
    q
      ? db.user.findMany({
          where,
          orderBy: [{ email: "asc" }],
          take: SEARCH_LIMIT,
          select: {
            id: true,
            email: true,
            name: true,
            _count: { select: { supportNotes: true } },
          },
        })
      : Promise.resolve([]),
  ]);

  return (
    <div className="mx-auto max-w-5xl px-6 py-10">
      <div className="mb-8">
        <Link
          href="/admin/feedback"
          className="rounded text-xs text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
        >
          ← Support inbox
        </Link>
        <div className="mt-1 text-lg font-semibold tracking-tight">Operator notes</div>
        <p className="text-sm text-black/60 dark:text-white/60">
          What we have written down about individual customers, so the next person picking up a
          thread has the context. Never shown to the customer — and always disclosable to them.
        </p>
      </div>

      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-3">
        <StatTile label="Notes written" value={noteTotal} />
        <StatTile label="Customers with notes" value={customersWithNotes} />
        <StatTile
          label="Last note"
          value={
            recent.length === 0 ? (
              <span className="text-black/30 dark:text-white/30">—</span>
            ) : (
              <span className="text-base">{formatDateTime(recent[0].createdAt).slice(0, 10)}</span>
            )
          }
          hint={recent.length === 0 ? "nobody has written one yet" : `by ${recent[0].authorEmail}`}
        />
      </div>

      <div className="mb-8">
        <Panel
          title="Find a customer"
          subtitle="Search by email, display name, or a user id pasted out of a ticket. Every customer has a note page, whether or not anything is written on it yet."
        >
          <form method="get" action="/admin/feedback/notes" className="flex flex-wrap items-center gap-2">
            <label htmlFor="note-search" className="sr-only">
              Search customers by email, name or user id
            </label>
            <input
              id="note-search"
              type="search"
              name="q"
              defaultValue={q}
              placeholder="Search email, name or user id"
              className={`w-full max-w-sm placeholder:text-black/40 dark:placeholder:text-white/40 ${controlClass}`}
            />
            <button type="submit" className={buttonClass}>
              Search
            </button>
            {q ? (
              <Link
                href="/admin/feedback/notes"
                className="rounded text-sm text-black/50 underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:text-white/50 dark:focus-visible:ring-white/40"
              >
                Clear
              </Link>
            ) : null}
          </form>

          {q ? (
            <div className="mt-4">
              {matches.length === 0 ? (
                <Empty>No customers match “{truncate(q, 40)}”.</Empty>
              ) : (
                <TableFrame>
                  <thead>
                    <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                      <Th>Customer</Th>
                      <Th align="right">Notes</Th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-black/10 dark:divide-white/10">
                    {matches.map((m) => (
                      <tr key={m.id}>
                        <td className="max-w-md px-4 py-2">
                          <Link
                            href={`/admin/feedback/notes/${m.id}`}
                            className="rounded font-medium underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
                          >
                            {truncate(m.email, 48)}
                          </Link>
                          {m.name ? (
                            <div className="text-xs text-black/50 dark:text-white/50">
                              {truncate(m.name, 48)}
                            </div>
                          ) : null}
                        </td>
                        <td className="px-4 py-2 text-right tabular-nums text-black/70 dark:text-white/70">
                          {m._count.supportNotes}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </TableFrame>
              )}
              {matches.length === SEARCH_LIMIT ? (
                <p className="mt-2 text-xs text-black/50 dark:text-white/50">
                  Showing the first {SEARCH_LIMIT} matches — narrow the search if the one you want
                  is not here.
                </p>
              ) : null}
            </div>
          ) : null}
        </Panel>
      </div>

      <Panel
        title="Recent notes"
        subtitle={
          noteTotal > recent.length
            ? `Newest first, across all customers. Showing the most recent ${recent.length} of ${noteTotal}.`
            : "Newest first, across all customers. Bodies are truncated here — open the customer for the whole note."
        }
      >
        {recent.length === 0 ? (
          <Empty>
            No support notes yet. Nothing is broken — this table starts empty and fills as people
            write in it.
          </Empty>
        ) : (
          <TableFrame>
            <thead>
              <tr className="border-b border-black/10 text-xs text-black/50 dark:border-white/10 dark:text-white/50">
                <Th>When</Th>
                <Th>Customer</Th>
                <Th>Author</Th>
                <Th>Note</Th>
              </tr>
            </thead>
            <tbody className="divide-y divide-black/10 dark:divide-white/10">
              {recent.map((n) => (
                <tr key={n.id}>
                  <td className="whitespace-nowrap px-4 py-2 tabular-nums text-black/70 dark:text-white/70">
                    {formatDateTime(n.createdAt)}
                  </td>
                  <td className="max-w-[14rem] px-4 py-2">
                    <Link
                      href={`/admin/feedback/notes/${n.userId}`}
                      className="rounded underline-offset-4 hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-black/40 dark:focus-visible:ring-white/40"
                    >
                      {truncate(n.user.email, 30)}
                    </Link>
                  </td>
                  <td className="max-w-[12rem] px-4 py-2 text-black/60 dark:text-white/60">
                    {truncate(n.authorEmail, 24)}
                  </td>
                  <td className="max-w-md px-4 py-2 text-black/70 dark:text-white/70">
                    {truncate(n.body.replace(/\s+/g, " "), 90)}
                  </td>
                </tr>
              ))}
            </tbody>
          </TableFrame>
        )}
      </Panel>

      <p className="mt-6 text-xs text-black/50 dark:text-white/50">
        Notes are append-only and attributed to whoever was signed in. They are internal, but a
        data-subject access request obliges us to hand a customer everything we hold about them —
        these rows included. Write what you would stand behind if they read it.
      </p>
    </div>
  );
}

