// Temporary verification fixture for the support inbox. Everything it writes is
// tagged so cleanup.js can remove exactly these rows and nothing else.
const { PrismaClient } = require("@prisma/client");
const { createHash } = require("node:crypto");
const p = new PrismaClient();

const TOKEN = "inbox-verify-token-do-not-ship";
const ADMIN_EMAIL = "inbox-verify-admin@kodely.local";
const MODE = process.argv[2] || "reliability";

const REASONS = [
  "looks-generic",
  "wrong-content",
  "layout-off",
  "missing-something",
  "broken",
  "other",
];

(async () => {
  const admin = await p.user.upsert({
    where: { email: ADMIN_EMAIL },
    update: { role: "ADMIN" },
    create: { email: ADMIN_EMAIL, name: "Inbox Verifier", role: "ADMIN" },
  });

  await p.session.deleteMany({ where: { userId: admin.id } });
  await p.session.create({
    data: {
      userId: admin.id,
      tokenHash: createHash("sha256").update(TOKEN).digest("hex"),
      expiresAt: new Date(Date.now() + 86400000),
    },
  });

  const users = await p.user.findMany({ where: { role: "CUSTOMER" }, select: { id: true } });
  const projects = await p.project.findMany({ select: { id: true } });
  const builds = await p.build.findMany({ select: { id: true, projectId: true } });

  await p.event.deleteMany({ where: { name: "build.rated" } });

  // 12 first-try + 12 repaired, with the down/up split chosen per mode so both
  // branches of the correlation read-out can be checked.
  const split =
    MODE === "quality"
      ? { cleanDown: 4, repairedDown: 4 } // ~33% vs ~33% -> "quality"
      : { cleanDown: 2, repairedDown: 8 }; // ~17% vs ~67% -> "reliability"

  const rows = [];
  let n = 0;
  for (const [bucket, repairs, downs] of [
    ["clean", 0, split.cleanDown],
    ["repaired", 1, split.repairedDown],
  ]) {
    for (let i = 0; i < 12; i++) {
      const down = i < downs;
      const b = builds[n % builds.length];
      rows.push({
        name: "build.rated",
        userId: users[n % users.length].id,
        createdAt: new Date(Date.now() - n * 3600_000),
        props: {
          buildId: b ? b.id : `synthetic-build-${n}`,
          projectId: b ? b.projectId : projects[n % projects.length].id,
          rating: down ? "down" : "up",
          repairAttempts: repairs === 0 ? 0 : 1 + (i % 2),
          model: "claude-sonnet-4-5-20250929",
          // One thumbs-down deliberately leaves no reason, to exercise that row.
          ...(down && i > 0 ? { reason: REASONS[(n + i) % REASONS.length] } : {}),
        },
      });
      n++;
    }
    void bucket;
  }

  // One event written before repairAttempts existed, to exercise "Not recorded".
  rows.push({
    name: "build.rated",
    userId: null,
    createdAt: new Date(Date.now() - 100 * 3600_000),
    props: { buildId: "legacy-build", rating: "down", model: "claude-sonnet-4-5-20250929" },
  });

  await p.event.createMany({ data: rows });

  // Two operator notes on a real customer.
  const target = users[0];
  await p.supportNote.deleteMany({ where: { authorEmail: ADMIN_EMAIL } });
  await p.supportNote.createMany({
    data: [
      {
        userId: target.id,
        authorEmail: ADMIN_EMAIL,
        body: "Emailed about the hero section being rebuilt on every edit.\nReproduced on their project; looks like the repair loop rewriting the whole file.",
      },
      {
        userId: target.id,
        authorEmail: ADMIN_EMAIL,
        body: "Follow-up: they are happy with the workaround. No refund requested.",
      },
    ],
  });

  console.log(
    JSON.stringify({
      mode: MODE,
      adminId: admin.id,
      token: TOKEN,
      targetUserId: target.id,
      events: rows.length,
    }),
  );
  await p.$disconnect();
})().catch((e) => {
  console.error(e);
  process.exit(1);
});

